// Convierte las respuestas del formulario en la petición que espera el agente.
const f = $input.first().json;
const campo = (etiqueta) => (f[etiqueta] ?? '').toString().trim();

const tipos = { 'Lanzamiento': 'lanzamiento', 'Promoción': 'promo', 'Estacional': 'estacional', 'Informativa': 'informativa' };
const lineas = (t) => t.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);

// Productos: una línea por producto → Nombre | Descripción | URL del producto | URL de la imagen
const productos = lineas(campo('Productos')).map((l) => {
  const [nombre, descripcion, url, imagen] = l.split('|').map((x) => (x ?? '').trim());
  const p = { nombre };
  if (descripcion) p.descripcion = descripcion;
  if (/^https?:\/\//.test(url ?? '')) p.url = url;
  if (/^https?:\/\//.test(imagen ?? '')) p.imagen = imagen;
  return p;
}).filter((p) => p.nombre);

const imagenes = lineas(campo('URLs de imágenes')).filter((u) => /^https?:\/\//.test(u)).map((url) => ({ url }));

// Imágenes subidas en el formulario → base64 (el agente las sube a Mailrelay).
const adjuntos = [];
const binarios = $input.first().binary ?? {};
for (const clave of Object.keys(binarios)) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, clave);
  adjuntos.push({ nombre: binarios[clave].fileName ?? `${clave}.jpg`, contenido_base64: buffer.toString('base64') });
}

const mensaje = campo('Mensaje y textos clave');
const fecha = campo('Fecha de envío').slice(0, 10);
const hora = (campo('Hora de envío').match(/^(\d{1,2})[:.](\d{2})/) ?? [null, '09', '00']).slice(1).map((x) => x.padStart(2, '0')).join(':');

return [{ json: {
  marca: 'betreson',
  tipo_campana: tipos[campo('Tipo de campaña')] ?? 'informativa',
  objetivo: campo('Objetivo'),
  asunto_sugerido: campo('Asunto sugerido') || undefined,
  mensaje,
  textos_clave: [],
  productos,
  imagenes,
  adjuntos,
  idioma: 'es',
  propuestas: campo('Propuestas').startsWith('2') ? 2 : 1,
  solicitante_email: campo('Tu email').toLowerCase(),
  destinatarios_prueba: campo('Enviar la prueba también a') || undefined,
  fecha_envio: `${fecha}T${hora}`,
} }];

const f = $('Formulario de newsletter').first().json;
const err = $input.first().json.error ?? $input.first().json;
return [{ json: {
  para: (f['Tu email'] ?? '').toString(),
  asunto: 'No se ha podido iniciar tu newsletter',
  html: `<p>El agente de newsletters no ha aceptado la petición.</p><pre style="white-space:pre-wrap">${JSON.stringify(err, null, 2).replace(/</g, '&lt;')}</pre><p>Revisa los datos del formulario o avisa a Digital.</p>`,
} }];
